namespace GenTRAC.DataBridge.DTO
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using IES.Standard;

    /// <summary>
    /// Class to encapsulate online users, number, who, etc...
    /// </summary>
    [Serializable()]
    public class UsersOnlineDTO : UpdateableDTO, IES.Standard.Interfaces.ICachableDTO
    {
        /// <summary>
        /// String for no current user proposal 
        /// </summary>
        private const string NO_PROPOSAL_TAG = "[none]";

        /// <summary>
        /// Dictionary that keeps track of users logged into system.  Keyed by ntid, has stats
        /// on the user in the system.
        /// </summary>
        private Dictionary<string, UserDTO> allUserDetails = new Dictionary<string, UserDTO>();

        /// <summary>
        /// Descriptor for All Users
        /// </summary>
        private UsersOnlineDetailDescriptor allUsersDescriptor = new UsersOnlineDetailDescriptor();

        /// <summary>
        /// object to lock on for details adjustement
        /// </summary>
        private static object LOCK = new object();

        /// <summary>
        /// number of minutes to wait until we evict user from the details dictionary
        /// </summary>
        private int MINUTES_EXPIRATION = 10;

        /// <summary>
        /// default constructor
        /// </summary>
        public UsersOnlineDTO()
        {
            allUsersDescriptor.MinutesToExpireUsers = MINUTES_EXPIRATION;
        }

        /// <summary>
        /// for ICachableDTO..
        /// </summary>
        /// <returns>Primary Key</returns>
        public int GetPrimaryKeyID()
        {
            return this.Id;
        }

        /// <summary>
        /// for ICachableDTO..
        /// </summary>
        /// <returns>Primary Key</returns>
        public string GetCacheID()
        {
            return CacheConstants.USERS_ONLINE;
        }

        /// <summary>
        /// Determines if a user is already part of the allUserDetails dictionary
        /// </summary>
        /// <param name="inDomainAndNtid">domain\userid</param>
        /// <returns>true if user is already part of the dictionary, false if not</returns>
        public bool ContainsUser(string inDomainAndNtid)
        {
            return allUserDetails.ContainsKey(inDomainAndNtid);
        }

        /// <summary>
        /// Determines if a user is already part of the allUserDetails dictionary
        /// </summary>
        /// <param name="inUserData">UserData object</param>
        /// <returns>true if user is already part of the dictionary, false if not</returns>
        private bool ContainsUser(UserData inUserData)
        {
            string key = inUserData.Ntid;
            return (allUserDetails.ContainsKey(key));
        }

        /// <summary>
        /// Adds a user if not part of the list of users logged into the system.
        /// Otherwise, we update the user's last access time.  Finally in both cases,
        /// prune the list of users that haven't been active for while.
        /// </summary>
        /// <param name="user">user</param>
        /// <param name="inTrackingNumber">proposal tracking number</param>
        public void UpdateUsersStatus(UserData user, string inTrackingNumber)
        {
            if (user == null)
            {
                throw new ArgumentNullException(nameof(user));
            }

            if (ContainsUser(user))
            {
                this.UpdateLastAccessTime(user.Ntid, inTrackingNumber);
            }
            else
            {
                this.AddUser(user, inTrackingNumber);
            }

            this.PruneUsers();
        }

        /// <summary>
        /// Update the last access time of the user with the matching domain and ntid
        /// </summary>
        /// <param name="inNtid">ntid of the user to update</param>
        /// <param name="inTrackingNumber">proposal tracking number</param>
        public void UpdateLastAccessTime(string inNtid, string inTrackingNumber)
        {
            lock (LOCK)
            {
                string key = inNtid;

                allUserDetails[key].TimeLastAccessed = DateTime.Now;

                if ((string.IsNullOrEmpty(allUserDetails[key].LastProposalAccessed) ||
                allUserDetails[key].LastProposalAccessed.Equals(UsersOnlineDTO.NO_PROPOSAL_TAG)) &&
                (string.IsNullOrEmpty(inTrackingNumber)))
                {
                    allUserDetails[key].LastProposalAccessed = UsersOnlineDTO.NO_PROPOSAL_TAG;
                }
                else if (!string.IsNullOrEmpty(inTrackingNumber))
                {
                    allUserDetails[key].LastProposalAccessed = inTrackingNumber;
                }
            }
        }

        /// <summary>
        /// Add a user to the user details.
        /// </summary>
        /// <param name="inUserData">user information to add</param>
        /// <param name="inProgram">the last program the user accessed</param>
        /// <param name="inTrackingNumber">proposal tracking number</param>
        public void AddUser(UserData inUserData, string inTrackingNumber)
        {
            if (inUserData == null)
            {
                throw new ArgumentNullException(nameof(inUserData));
            }

            lock (LOCK)
            {
                string key = inUserData.Ntid;
                if (!allUserDetails.ContainsKey(key))
                {
                    // prune users that are older than time allowed so we don't inflate the peak users
                    // with expired users
                    this.PruneUsers();

                    allUserDetails.Add(key, new UserDTO
                    {
                        DisplayName = inUserData.DisplayName,
                        Ntid = inUserData.Ntid,
                        TimeLastAccessed = DateTime.Now,
                        LastProposalAccessed = string.IsNullOrEmpty(inTrackingNumber) ? UsersOnlineDTO.NO_PROPOSAL_TAG : inTrackingNumber
                    });

                    // update peak if need be
                    if (allUserDetails.Count > allUsersDescriptor.PeakUsersSinceCacheClear)
                    {
                        allUsersDescriptor.PeakUsersSinceCacheClear = allUserDetails.Count;
                    }
                }
            }
        }

        /// <summary>
        /// Remove user from the user information details
        /// </summary>
        /// <param name="inUserToRemove">user to remove</param>
        public void RemoveUser(UserDTO inUserToRemove)
        {
            if (inUserToRemove == null)
            {
                throw new ArgumentNullException(nameof(inUserToRemove));
            }

            // we don't want multiple threads in here pruning the dictionary at the same time ..
            lock (LOCK)
            {
                // evict user
                allUserDetails.Remove(inUserToRemove.Ntid);
            }
        }

        /// <summary>
        /// Gets a list of all the user descriptors
        /// </summary>
        /// <returns></returns>
        public UsersOnlineDetailDescriptor GetAllUsers()
        {
            this.allUsersDescriptor.UserOnlineDetailsCollection = this.allUserDetails.Values.OrderByDescending(v => v.TimeLastAccessed).ToArray();

            return this.allUsersDescriptor;
        }

        /// <summary>
        /// Prune users out of the dictionary that are older than some period of time
        /// </summary>
        public void PruneUsers()
        {
            lock (LOCK)
            {
                // first clone the dictionary keys to avoid collection changes while iterating
                string[] keys = allUserDetails.Keys.ToArray();
                foreach (string ntid in keys)
                {
                    UserDTO details = allUserDetails[ntid];

                    if ((DateTime.Now - details.TimeLastAccessed).TotalMinutes > MINUTES_EXPIRATION)
                    {
                        // evict user
                        allUserDetails.Remove(ntid);
                    }
                }
            }
        }
    }
}

